sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;

    var inputs = {};
    inputs['company'] = body.company; 

    try {
        var result = sn_fd.FlowAPI.getRunner()
            .action('x_1815796_itsmgr_0.getclosestcompany')
            .inForeground()
            .withInputs(inputs)
            .run();

        var outputs = result.getOutputs();

        var matched_name = outputs['matched_name']; 
        var matched_name_ai = outputs['matched_name_ai']; 
        var definitive_name = outputs['definitive_name']; 

        gs.info("Get Closest Company Action Executed Successfully. Definitive Name: " + definitive_name);

        response.setStatus(200);
        response.setBody({
            "status": "success",
            "matched_name": matched_name,
            "matched_name_ai": matched_name_ai,
            "definitive_name": definitive_name
        });

    } catch (ex) {
        var errorMessage = ex.message || ex.toString();
        gs.error("Error in Scripted REST API (Get Closest Company): " + errorMessage);

        response.setStatus(500);
        response.setBody({
            "status": "failure",
            "message": errorMessage
        });
    }
})(request, response);
